/* Final Sarthi UI polish: compact, high-contrast, image-first commerce surfaces.
   This layer uses the palette tokens from base.css. */

html {
  background: var(--bg-canvas);
}

body {
  background: var(--bg-canvas);
  color: var(--text-primary);
}

h1,
h2,
h3,
h4,
h5,
h6 {
  color: var(--text-primary);
  letter-spacing: 0;
}

p {
  color: var(--text-secondary);
}

button,
input,
select,
textarea {
  letter-spacing: 0;
}

select,
textarea,
input {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  color: var(--text-primary);
}

select:focus,
textarea:focus,
input:focus {
  border-color: var(--accent-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent-primary) 18%, transparent);
}

.web-app-container {
  background: transparent;
}

.web-header {
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 16px 18px 8px;
}

.commerce-header-container {
  background: color-mix(in srgb, var(--bg-surface) 84%, transparent);
  border: 1px solid color-mix(in srgb, var(--border-subtle) 82%, transparent);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
  max-width: 1120px;
  min-height: 58px;
  padding: 8px 12px;
}

.web-brand-badge {
  background: var(--text-primary);
  border-radius: 8px;
  color: var(--bg-canvas);
  height: 34px;
  width: 34px;
}

.web-brand-title {
  color: var(--text-primary);
  font-size: 18px;
}

.web-brand-subtitle {
  color: var(--text-secondary);
  font-size: 10px;
}

.commerce-nav {
  background: color-mix(in srgb, var(--bg-surface-muted) 75%, transparent);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  display: flex;
  flex-wrap: wrap;
  gap: 2px;
  max-width: 100%;
  overflow: visible;
  padding: 4px;
}

.commerce-nav button,
.commerce-role-lock {
  border-radius: 999px;
  color: var(--text-secondary);
  min-height: 34px;
  padding: 7px 14px;
}

.commerce-nav button.active {
  background: var(--text-primary);
  color: var(--bg-canvas);
}

.commerce-nav button:hover {
  background: color-mix(in srgb, var(--text-primary) 10%, transparent);
  color: var(--text-primary);
}

.web-header-btn,
.web-header-select,
.commerce-account {
  background: color-mix(in srgb, var(--bg-surface-muted) 78%, transparent);
  border-color: var(--border-subtle);
  border-radius: 999px;
  color: var(--text-primary);
}

.commerce-mode-btn {
  background: color-mix(in srgb, var(--success) 14%, var(--bg-surface));
  color: var(--success);
}

.web-header-select select {
  color: var(--text-primary);
}

.commerce-account-name small,
.role-pill {
  color: var(--accent-primary);
}

.web-content-container {
  max-width: 100%;
  padding: 20px 16px 48px;
}

.eyebrow {
  color: var(--accent-primary);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0;
}

.ui-badge,
.product-trust-badge,
.radar-context-row span,
.radar-chip-row span,
.cart-confidence-chips span,
.lens-evidence-chips span,
.lens-guard-row span,
.marketplace-category-row button,
.trust-chip-list span {
  border-radius: 999px;
}

.notice {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  color: var(--text-primary);
}

.notice.error,
.auth-error-banner {
  background: color-mix(in srgb, var(--error) 13%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--error) 38%, var(--border-subtle));
  color: var(--error);
}

.notice.success,
.auth-success-banner {
  background: color-mix(in srgb, var(--success) 12%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 34%, var(--border-subtle));
  color: var(--success);
}

/* Auth */
.mobile-auth-container.auth-entry-shell {
  align-items: center;
  display: grid;
  min-height: calc(100vh - 150px);
  padding: 18px;
}

.mobile-auth-card.auth-entry-card {
  background: color-mix(in srgb, var(--bg-surface) 92%, transparent);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: var(--shadow-lg);
  max-width: 420px !important;
  padding: 20px;
}

.auth-brand-lockup {
  justify-content: center;
  margin-bottom: 14px;
}

.brand-logo-badge {
  background: var(--text-primary);
  color: var(--bg-canvas);
}

.brand-logo-text,
.brand-logo-sub {
  color: var(--text-primary);
}

.brand-logo-sub {
  color: var(--text-secondary);
}

.auth-portal-grid {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  padding: 5px;
}

.auth-portal-card {
  background: transparent;
  border: 0;
  border-radius: 8px;
  color: var(--text-secondary);
}

.auth-portal-card.active {
  background: var(--text-primary);
  color: var(--bg-canvas);
}

.auth-portal-card.active span,
.auth-portal-card.active strong {
  color: var(--bg-canvas);
}

.auth-portal-summary,
.auth-security-note,
.demo-credential-box,
.auth-form-step {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  border-radius: 8px;
}

.auth-step-heading {
  font-size: 22px;
}

.auth-step-desc,
.auth-portal-lock,
.auth-security-note {
  color: var(--text-secondary);
  font-size: 12px;
}

.auth-tab-group {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  padding: 4px;
}

.auth-tab-btn {
  border-radius: 999px;
  color: var(--text-secondary);
}

.auth-tab-btn.active {
  background: var(--accent-primary);
  color: var(--text-on-accent);
}

.auth-input-group label {
  color: var(--text-secondary);
}

.auth-primary-btn,
.btn-primary,
.lens-primary-action,
.seller-primary-action,
.admin-approve,
.sarthi-toast-action,
.decision-question-input button {
  background: var(--accent-primary);
  border: 1px solid color-mix(in srgb, var(--accent-primary) 60%, transparent);
  border-radius: 8px;
  color: var(--text-on-accent);
  box-shadow: 0 12px 28px color-mix(in srgb, var(--accent-primary) 22%, transparent);
}

/* Buyer catalog */
.marketplace-home {
  gap: 14px;
}

.marketplace-toolbar,
.marketplace-trust-strip,
.trust-radar-card,
.cart-confidence-card,
.sarthi-lens-panel,
.workspace-hero,
.workspace-flow-strip,
.workspace-insight-card,
.workspace-column,
.kg-card,
.trust-card,
.trust-metric-card,
.admin-review-section,
.admin-policy-card,
.admin-review-card,
.admin-doc-row,
.seller-section,
.seller-listing-card,
.seller-metric-tile,
.bottom-sheet-content {
  background: color-mix(in srgb, var(--bg-surface) 92%, transparent);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.marketplace-search-bar,
.marketplace-location {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  border-radius: 8px;
}

.marketplace-category-row button {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  color: var(--text-primary);
}

.marketplace-category-row button:hover,
.marketplace-category-row button.active {
  background: var(--text-primary);
  border-color: var(--text-primary);
  color: var(--bg-canvas);
}

.shop-section-heading {
  margin-top: 10px;
}

.shop-section-heading h3 {
  font-size: 22px;
}

.buyer-shop-shell .web-product-grid {
  grid-template-columns: repeat(auto-fill, minmax(204px, 1fr));
  gap: 14px;
}

.buyer-product-card {
  background: color-mix(in srgb, var(--bg-surface) 94%, transparent);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: none;
  overflow: hidden;
}

.buyer-product-card:hover {
  border-color: color-mix(in srgb, var(--accent-primary) 54%, var(--border-subtle));
  transform: translateY(-2px);
}

.buyer-product-image {
  background: var(--bg-surface-muted);
  aspect-ratio: 1 / 1;
  border: 0;
  border-radius: 0;
}

.buyer-product-body {
  padding: 12px;
}

.buyer-product-title {
  color: var(--text-primary);
  font-size: 12.5px;
  line-height: 1.25;
  min-height: 32px;
}

.product-price-row strong {
  color: var(--success);
}

.lens-secondary-action,
.radar-action-row button,
.btn-secondary,
.seller-secondary-action,
.admin-refresh-button,
.workspace-back-button {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  color: var(--text-primary);
}

/* Saved trust workspace */
.sarthi-saved-workspace {
  padding: 0;
}

.workspace-hero {
  align-items: center;
  margin: 0;
  padding: 14px;
}

.workspace-hero-left {
  gap: 12px;
}

.workspace-hero-left > img {
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
}

.workspace-product-copy h2 {
  font-size: 28px;
}

.workspace-product-copy p {
  color: var(--text-secondary);
  max-width: 620px;
}

.workspace-score-summary {
  background: var(--text-primary);
  border: 0;
  color: var(--bg-canvas);
}

.workspace-score-summary span,
.workspace-score-summary small {
  color: color-mix(in srgb, var(--bg-canvas) 78%, transparent);
}

.workspace-score-summary strong {
  color: var(--success);
}

.workspace-flow-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  padding: 8px;
}

.workspace-flow-strip span {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  color: var(--text-secondary);
  justify-content: center;
}

.workspace-flow-strip span.complete {
  background: color-mix(in srgb, var(--success) 12%, var(--bg-surface));
  color: var(--success);
}

.workspace-insight-row {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.workspace-insight-card {
  min-height: 96px;
  padding: 14px;
}

.workspace-insight-card > svg {
  color: var(--accent-primary);
}

.workspace-insight-card strong {
  color: var(--text-primary);
  font-size: 24px;
}

.workspace-grid-upgraded {
  grid-template-columns: minmax(360px, 0.9fr) minmax(520px, 1.1fr);
}

.trust-radar-card,
.sarthi-lens-panel {
  padding: 14px;
}

.radar-score,
.cart-score-pill,
.lens-score-badge {
  background: var(--text-primary);
  border: 0;
  color: var(--bg-canvas);
}

.radar-score strong,
.cart-score-pill strong,
.lens-score-badge strong {
  color: var(--success);
}

.radar-score span,
.cart-score-pill span,
.lens-score-badge span {
  color: color-mix(in srgb, var(--bg-canvas) 72%, transparent);
}

.radar-recommendation-row,
.radar-action-row,
.lens-clean-summary,
.lens-selected-strip,
.lens-seller-list,
.lens-seller-row,
.decision-question-box,
.kg-simple-details,
.kg-decision-row,
.cart-line-summary div,
.trust-step-card,
.trust-guidance-box,
.memory-record-row,
.readiness-status-row,
.admin-detail,
.seller-data-point,
.seller-score-box,
.seller-action-item,
.seller-proof-task {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  border-radius: 8px;
}

.radar-context-row span,
.radar-chip-row span,
.lens-evidence-chips span {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
}

/* Knowledge graph */
.kg-card {
  padding: 14px;
}

.kg-real-graph {
  background:
    linear-gradient(var(--border-subtle) 1px, transparent 1px),
    linear-gradient(90deg, var(--border-subtle) 1px, transparent 1px),
    var(--bg-surface);
  background-size: 44px 44px;
  border-color: var(--border-subtle);
  border-radius: 8px;
  min-height: 390px;
}

.kg-system-strip span,
.kg-graph-toolbar button,
.kg-zoom-controls,
.kg-live-pill,
.kg-header-row span,
.kg-real-edge-label {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  border-radius: 999px;
  color: var(--text-primary);
}

.kg-real-node {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 2px;
  color: var(--text-primary);
  box-shadow: none;
  font-family: 'Courier Prime', monospace;
}

.kg-real-node.safe {
  border-color: var(--stamp-verified);
  background: color-mix(in srgb, var(--stamp-verified) 4%, var(--bg-surface));
}

.kg-real-node.watch {
  border-color: var(--stamp-caution);
  background: color-mix(in srgb, var(--stamp-caution) 4%, var(--bg-surface));
}

.kg-real-node.danger {
  border-color: var(--stamp-danger);
  background: color-mix(in srgb, var(--stamp-danger) 4%, var(--bg-surface));
}

.kg-real-node-icon {
  background: color-mix(in srgb, var(--border-subtle) 25%, transparent);
  border-radius: 1px;
}

.kg-real-edge {
  stroke-width: 1.2;
  stroke-dasharray: 4 4;
}

.kg-real-edge.highlighted,
.kg-real-edge.selected,
.kg-real-edge.connected {
  stroke-dasharray: none;
  stroke-width: 2;
}

.kg-chat-input input,
.decision-question-input input {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
}

/* Trust, seller, admin */
.trust-center-shell,
.seller-console-shell,
.admin-review-shell {
  max-width: 100%;
  padding: 0;
  margin: 0;
}

.trust-hero-section,
.admin-hero,
.seller-console-toolbar {
  background: transparent;
  border: 0;
  box-shadow: none;
  padding: 6px 0 0;
}

.trust-hero-section h2,
.admin-hero h2,
.seller-title-block h2 {
  font-size: 44px;
  line-height: 0.98;
  text-transform: uppercase;
}

.trust-hero-simple p,
.admin-hero p,
.seller-title-block p {
  color: var(--text-secondary);
  max-width: 620px;
}

.trust-summary-grid,
.seller-stats-band,
.admin-stats-grid {
  gap: 12px;
}

.trust-metric-card,
.seller-metric-tile,
.admin-stat-card {
  background: color-mix(in srgb, var(--bg-surface) 92%, transparent);
  border-color: var(--border-subtle);
  border-radius: 8px;
}

.trust-metric-card strong,
.seller-metric-tile strong,
.admin-stat-card strong,
.seller-current-rating strong {
  color: var(--success);
}

.trust-icon-badge,
.seller-metric-icon,
.admin-stat-card .seller-metric-icon {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  color: var(--accent-primary);
}

.trust-chip-list span {
  background: color-mix(in srgb, var(--success) 10%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 26%, var(--border-subtle));
  color: var(--success);
}

.trust-chip-list.muted span {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  color: var(--text-secondary);
}

.seller-listing-image,
.seller-listing-image img {
  border-radius: 8px;
}

.seller-current-rating {
  background: var(--text-primary);
  border-radius: 8px;
  color: var(--bg-canvas);
}

.seller-current-rating small {
  color: color-mix(in srgb, var(--bg-canvas) 70%, transparent);
}

.seller-current-rating strong {
  color: var(--success);
  font-weight: 950;
}

.admin-action-row button,
.seller-card-actions button,
.seller-toolbar-controls button {
  border-radius: 8px;
}

.admin-reject,
.btn-danger {
  background: color-mix(in srgb, var(--error) 14%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--error) 40%, var(--border-subtle));
  color: var(--error);
}

/* Product detail and sheets */
.product-detail-header,
.detail-product-card,
.size-selector-card,
.keep-confidence-card,
.sku-passport-card,
.detail-evidence-card,
.detail-question-card,
.cod-action-card,
.expectation-preview-card,
.checkout-contract-card,
.checkout-payment-card,
.checkout-keep-card,
.checkout-check-card,
.trust-state-card,
.agent-check-card {
  background: color-mix(in srgb, var(--bg-surface) 92%, transparent);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  box-shadow: var(--shadow-sm);
}

.detail-image-frame {
  background: var(--bg-surface-muted);
  border-radius: 8px;
}

.detail-size-options button.active {
  background: var(--text-primary);
  color: var(--bg-canvas);
}

.bottom-sheet-overlay {
  background: rgba(0, 0, 0, 0.72);
}

.bottom-sheet-content {
  color: var(--text-primary);
}

@media (max-width: 900px) {
  .web-header {
    padding: 10px 10px 6px;
  }

  .commerce-header-container {
    border-radius: 18px;
    grid-template-columns: 1fr;
    padding: 10px;
  }

  .commerce-brand {
    min-height: 34px;
    padding-left: 2px;
  }

  .commerce-nav {
    justify-self: stretch;
  }

  .commerce-actions {
    display: grid;
    grid-template-columns: 1fr 1fr auto auto;
    width: 100%;
  }

  .commerce-select,
  .commerce-mode-btn {
    justify-content: center;
    min-width: 0;
  }

  .commerce-account {
    min-width: 0;
    padding-inline: 8px 4px;
  }

  .commerce-account-name {
    min-width: 0;
    overflow: hidden;
  }

  .commerce-account-name strong {
    max-width: 56px;
  }

  .web-content-container {
    padding: 18px 12px 34px;
  }

  .marketplace-category-row {
    margin-inline: -2px;
    max-width: 100%;
    overflow: visible;
    padding-bottom: 4px;
  }

  .workspace-grid-upgraded,
  .workspace-grid {
    grid-template-columns: 1fr;
  }

  .workspace-insight-row,
  .trust-summary-grid,
  .seller-stats-band,
  .admin-stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 520px) {
  body {
    background-size: auto, 54px 54px, auto;
  }

  .web-brand-subtitle,
  .commerce-account-name small,
  .hide-on-mobile {
    display: none;
  }

  .show-on-mobile {
    display: inline;
  }

  .commerce-actions {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) 40px 76px;
    gap: 8px;
  }

  .commerce-account-name {
    display: none;
  }

  .commerce-account {
    justify-content: center;
    max-width: 76px;
    width: 76px;
  }

  .web-header-btn,
  .web-header-select {
    min-height: 38px;
    padding-inline: 10px;
  }

  .web-user-menu {
    gap: 4px;
  }

  .buyer-shop-shell .web-product-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .buyer-product-body {
    padding: 10px;
  }

  .buyer-product-title {
    font-size: 12px;
    min-height: 31px;
  }

  .product-price-row {
    gap: 2px;
  }

  .workspace-hero {
    align-items: stretch;
    flex-direction: column;
  }

  .workspace-hero-left {
    display: grid;
    grid-template-columns: 98px minmax(0, 1fr);
  }

  .workspace-back-button {
    grid-column: 1 / -1;
    width: fit-content;
  }

  .workspace-product-copy h2 {
    font-size: 24px;
  }

  .workspace-score-summary {
    align-items: flex-start;
    width: 100%;
  }

  .workspace-flow-strip {
    grid-template-columns: 1fr 1fr;
  }

  .workspace-insight-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workspace-insight-card {
    min-height: 88px;
  }

  .kg-real-graph {
    min-height: 320px;
    overflow: auto;
  }

  .kg-real-node {
    min-width: 110px;
  }

  .trust-hero-section h2,
  .admin-hero h2,
  .seller-title-block h2 {
    font-size: 32px;
  }

  .trust-center-shell,
  .seller-console-shell,
  .admin-review-shell {
    padding: 0;
  }

  .seller-console-grid,
  .seller-main-column,
  .seller-side-column,
  .seller-section,
  .seller-evidence-coach,
  .seller-live-section,
  .seller-listing-stack,
  .seller-table-wrap {
    max-width: 100%;
    min-width: 0;
  }

  .seller-table-wrap {
    overflow-x: clip;
  }

  .trust-summary-grid,
  .seller-stats-band,
  .admin-stats-grid {
    grid-template-columns: 1fr;
  }

  .mobile-auth-container.auth-entry-shell {
    min-height: calc(100vh - 190px);
    padding: 8px 0 20px;
  }

  .mobile-auth-card.auth-entry-card {
    padding: 16px;
  }
}

/* Natural product typography and balanced page width */
:root {
  --app-shell-max: 1360px;
  --app-page-gutter: clamp(12px, 2vw, 28px);
}

body,
button,
input,
select,
textarea {
  font-family: var(--font-sans);
}

h1,
h2,
h3,
h4,
h5,
h6,
.web-brand-title,
.web-brand-badge,
.brand-badge,
.admin-stat-card strong,
.seller-metric-tile strong,
.trust-metric-card strong {
  font-family: var(--font-sans) !important;
  font-weight: 700 !important;
  letter-spacing: 0 !important;
}

strong,
b {
  font-weight: 700;
}

button,
.commerce-nav button,
.web-header-btn,
.web-header-select select,
.marketplace-cart-button,
.buyer-view-btn,
.buyer-save-btn,
.btn-action-primary,
.btn-action-secondary,
.btn-sticky-buy {
  font-weight: 600 !important;
}

.eyebrow,
.role-pill,
.commerce-account-name small,
.marketplace-category-row > span,
.admin-stat-card span,
.seller-table-wrap th,
.admin-table-wrap th,
.trust-section-label,
.seller-section-label,
.avoidable-issue-card span {
  font-size: 11px !important;
  font-weight: 600 !important;
  letter-spacing: 0 !important;
  text-transform: none !important;
}

.eyebrow,
.sheet-eyebrow-primary,
.sheet-eyebrow-secondary {
  color: var(--text-secondary);
}

.trust-hero-section h2,
.admin-hero h2,
.seller-title-block h2,
.buyer-shop-copy h2 {
  font-size: clamp(26px, 2.4vw, 36px) !important;
  line-height: 1.16 !important;
  text-transform: none !important;
}

.web-header {
  padding: 14px var(--app-page-gutter) 8px;
}

.commerce-header-container {
  margin-inline: auto;
  max-width: min(var(--app-shell-max), calc(100% - (var(--app-page-gutter) * 2)));
  width: 100%;
}

.web-content-container {
  padding: 18px var(--app-page-gutter) 50px;
}

.marketplace-home,
.buyer-shop-shell,
.buyer-workspace-shell,
.sarthi-saved-workspace,
.trust-center-shell,
.seller-console-shell,
.admin-review-shell {
  margin-inline: auto;
  max-width: min(var(--app-shell-max), 100%);
  width: 100%;
}

.product-detail-shell {
  margin-inline: auto;
  max-width: min(1320px, 100%);
  width: 100%;
}

.detail-product-summary h1 {
  font-size: clamp(20px, 1.45vw, 24px);
  line-height: 1.25;
}

.detail-price-row strong {
  font-size: clamp(24px, 1.8vw, 30px);
}

.trust-receipt-card h3,
.keep-confidence-card strong,
.cart-confidence-card > strong,
.cart-confidence-header strong,
.samvaad-card h3 {
  font-size: clamp(16px, 1.1vw, 19px);
  line-height: 1.25;
}

.product-trust-badge,
.ui-badge,
.cart-confidence-chips span,
.radar-chip-row span,
.trust-chip-list span {
  font-weight: 600 !important;
}

@media (min-width: 1200px) {
  .buyer-shop-shell .web-product-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
}

@media (min-width: 1440px) {
  :root {
    --app-shell-max: 1440px;
  }
}

@media (max-width: 900px) {
  .web-header {
    padding: 10px 12px 6px;
  }

  .web-content-container {
    padding: 14px 12px 38px;
  }

  .trust-hero-section h2,
  .admin-hero h2,
  .seller-title-block h2,
  .buyer-shop-copy h2 {
    font-size: 26px !important;
  }
}

/* Login shell: clean product entry, not a dashboard card */
.auth-entry-layout {
  align-items: stretch;
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(300px, 0.9fr) minmax(360px, 430px);
  margin-inline: auto;
  max-width: 980px;
  width: 100%;
}

.auth-story-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 560px;
  padding: 34px;
}

.auth-story-brand {
  align-items: center;
  display: flex;
  gap: 11px;
  margin-bottom: 34px;
}

.auth-story-brand strong,
.auth-story-brand span {
  display: block;
}

.auth-story-brand strong {
  color: var(--text-primary);
  font-size: 20px;
  line-height: 1;
}

.auth-story-brand span {
  color: var(--text-secondary);
  font-size: 12px;
  margin-top: 3px;
}

.auth-story-panel h2 {
  color: var(--text-primary);
  font-size: clamp(32px, 4vw, 52px);
  line-height: 1.02;
  margin: 0;
  max-width: 390px;
}

.auth-story-panel p {
  color: var(--text-secondary);
  font-size: 15px;
  line-height: 1.55;
  margin: 16px 0 0;
  max-width: 430px;
}

.auth-story-checks {
  display: grid;
  gap: 10px;
  margin-top: 28px;
}

.auth-story-checks span {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  color: var(--text-primary);
  display: inline-flex;
  font-size: 13px;
  gap: 8px;
  min-height: 38px;
  padding: 8px 12px;
  width: fit-content;
}

.auth-story-checks svg {
  color: var(--success);
}

.brand-logo-badge.auth-logo-mark {
  align-items: center;
  background: var(--text-primary);
  border-radius: 12px;
  color: var(--bg-surface);
  display: inline-grid;
  height: 44px;
  place-items: center;
  position: relative;
  width: 44px;
}

.brand-logo-badge.auth-logo-mark span {
  color: inherit;
  font-size: 21px;
  font-weight: 700;
  line-height: 1;
}

.brand-logo-badge.auth-logo-mark svg {
  background: var(--success);
  border: 2px solid var(--bg-surface);
  border-radius: 999px;
  bottom: -5px;
  color: var(--text-on-accent);
  height: 20px;
  padding: 3px;
  position: absolute;
  right: -5px;
  width: 20px;
}

.mobile-auth-card.auth-entry-card {
  align-self: stretch;
  border-radius: 14px;
  max-width: none !important;
  padding: 22px;
}

.auth-brand-lockup {
  justify-content: flex-start;
}

.auth-form-step,
.auth-portal-summary,
.demo-credential-box,
.auth-security-note {
  background: var(--bg-surface);
}

.auth-form-step {
  gap: 12px;
}

.auth-input-group {
  margin-bottom: 0;
}

.auth-input-group input,
.auth-input-group select {
  min-height: 44px;
}

.demo-credential-box {
  align-items: center;
  border-style: dashed;
}

.demo-credential-box button {
  background: var(--text-primary);
  border-radius: 8px;
  color: var(--bg-surface);
  min-height: 34px;
  padding: 8px 12px;
}

.auth-primary-btn {
  min-height: 46px;
}

@media (max-width: 860px) {
  .auth-entry-layout {
    grid-template-columns: 1fr;
    max-width: 460px;
  }

  .auth-story-panel {
    min-height: auto;
    padding: 22px;
  }

  .auth-story-panel h2 {
    font-size: 30px;
  }
}

/* Trust Center: compact account controls, not a landing page */
.trust-center-shell.trust-center-v5 {
  display: grid;
  gap: 14px;
  margin-inline: auto;
  max-width: min(1320px, 100%);
}

.trust-center-v5 .trust-account-header {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 16px 18px;
}

.trust-center-v5 .trust-title-block h2 {
  color: var(--text-primary);
  font-size: clamp(24px, 2vw, 32px) !important;
  line-height: 1.14 !important;
  margin: 4px 0 4px;
  text-transform: none !important;
}

.trust-center-v5 .trust-title-block p {
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.45;
  margin: 0;
  max-width: 620px;
}

.trust-header-meta,
.trust-header-actions,
.trust-quick-actions {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.trust-header-meta {
  margin-top: 10px;
}

.trust-header-meta span {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  color: var(--text-secondary);
  display: inline-flex;
  font-size: 12px;
  font-weight: 600;
  gap: 6px;
  min-height: 30px;
  padding: 6px 10px;
}

.trust-header-meta svg {
  color: var(--success);
}

.trust-center-v5 .trust-quick-actions {
  margin: 0;
}

.trust-center-v5 .trust-quick-actions button,
.trust-refresh-button {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  color: var(--text-primary);
  display: inline-flex;
  font-size: 13px;
  font-weight: 600;
  gap: 7px;
  justify-content: center;
  min-height: 38px;
  padding: 8px 12px;
}

.trust-center-v5 .trust-quick-actions button:hover,
.trust-refresh-button:hover {
  background: var(--bg-surface-muted);
}

.trust-refresh-button {
  width: 38px;
}

.trust-message-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.trust-center-v5 .trust-inline-message {
  border-radius: 9px;
  font-size: 13px;
  font-weight: 600;
  margin: 0;
  max-width: max-content;
  min-height: 38px;
  padding: 9px 12px;
}

.trust-snapshot-bar {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 1px;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
}

.trust-snapshot-bar > div {
  align-items: center;
  background: var(--bg-surface);
  display: grid;
  gap: 4px 9px;
  grid-template-columns: 18px minmax(0, 1fr);
  padding: 12px 14px;
}

.trust-snapshot-bar > div + div {
  border-left: 1px solid var(--border-subtle);
}

.trust-snapshot-bar svg {
  color: var(--text-secondary);
  grid-row: span 2;
}

.trust-snapshot-bar .safe svg {
  color: var(--success);
}

.trust-snapshot-bar .watch svg {
  color: var(--warning);
}

.trust-snapshot-bar span {
  color: var(--text-secondary);
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1;
}

.trust-snapshot-bar strong {
  color: var(--text-primary);
  display: block;
  font-size: 13.5px;
  font-weight: 700;
  line-height: 1.2;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.trust-center-v5 .trust-control-strip {
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(320px, 0.84fr) minmax(0, 1.16fr);
}

.trust-center-v5 .fit-help-control,
.trust-center-v5 .fit-learning-card,
.trust-center-v5 .fit-journey-preview,
.trust-center-v5 .checkout-guidance-line,
.trust-center-v5 .trust-card {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  box-shadow: var(--shadow-sm);
}

.trust-center-v5 .fit-help-control,
.trust-center-v5 .fit-learning-card,
.trust-center-v5 .fit-journey-preview {
  min-height: 0;
  padding: 16px;
}

.trust-center-v5 .fit-help-control h3,
.trust-center-v5 .fit-learning-card h3,
.trust-center-v5 .fit-journey-preview h3 {
  color: var(--text-primary);
  font-size: 18px;
  line-height: 1.2;
  margin: 3px 0 4px;
}

.trust-center-v5 .fit-help-control p,
.trust-center-v5 .fit-learning-card p,
.trust-center-v5 .fit-journey-preview p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.42;
}

.trust-center-v5 .trust-switch-button {
  border-radius: 12px;
  min-height: 42px;
  padding: 6px 10px 6px 6px;
}

.trust-center-v5 .trust-switch-track {
  height: 26px;
  width: 48px;
}

.trust-center-v5 .trust-switch-track span {
  height: 20px;
  width: 20px;
}

.trust-center-v5 .fit-help-control.enabled .trust-switch-track span {
  transform: translateX(22px);
}

.trust-center-v5 .fit-learning-card {
  align-items: center;
  grid-template-columns: minmax(0, 1fr) auto;
}

.trust-center-v5 .fit-learning-head {
  align-items: center;
}

.trust-center-v5 .fit-learning-card > .btn-primary {
  border-radius: 9px;
  justify-self: end;
  min-height: 38px;
  padding: 8px 14px;
  width: auto;
}

.trust-center-v5 .fit-quiz-panel {
  grid-column: 1 / -1;
}

.trust-center-v5 .checkout-guidance-line {
  align-items: center;
  grid-template-columns: 22px minmax(0, 1fr);
  padding: 12px 14px;
}

.trust-center-v5 .trust-center-grid {
  align-items: start;
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(0, 1fr) minmax(300px, 0.38fr);
}

.trust-center-v5 .trust-main-column,
.trust-center-v5 .trust-side-column {
  display: grid;
  gap: 14px;
}

.trust-center-v5 .trust-card {
  padding: 16px;
}

.trust-center-v5 .trust-card-header {
  align-items: flex-start;
  display: flex;
  gap: 12px;
  justify-content: space-between;
  margin-bottom: 12px;
}

.trust-center-v5 .trust-card-header h3,
.trust-center-v5 .review-fairness-card h3 {
  color: var(--text-primary);
  font-size: 17px;
  line-height: 1.22;
  margin: 2px 0 0;
}

.trust-center-v5 .trust-card-header p,
.trust-center-v5 .review-fairness-card p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.42;
}

.trust-center-v5 .plain-proof-list,
.trust-center-v5 .fit-journey-list {
  gap: 8px;
}

.trust-center-v5 .plain-proof-row,
.trust-center-v5 .fit-journey-item,
.trust-center-v5 .logged-reason-line,
.trust-center-v5 .order-exclusion-line {
  background: var(--bg-surface-muted);
  border-color: var(--border-subtle);
  border-radius: 9px;
}

.trust-center-v5 .plain-proof-row span,
.trust-center-v5 .fit-journey-summary strong,
.trust-center-v5 .logged-reason-line strong {
  color: var(--text-primary);
  font-weight: 600;
}

.trust-center-v5 .proof-detail-toggle,
.trust-center-v5 .btn-secondary,
.trust-center-v5 .btn-danger {
  border-radius: 9px;
  min-height: 36px;
}

.trust-center-v5 .trust-data-card {
  display: grid;
  gap: 10px;
}

.trust-center-v5 .trust-icon-badge {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 9px;
  color: var(--text-secondary);
  display: inline-flex;
  height: 34px;
  justify-content: center;
  width: 34px;
}

.trust-center-v5 .trust-data-card.safe .trust-icon-badge {
  color: var(--success);
}

.trust-center-v5 .trust-chip-list {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.trust-center-v5 .trust-chip-list span,
.trust-center-v5 .fit-memory-mini-list span,
.trust-center-v5 .fit-journey-summary small {
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
}

@media (max-width: 1100px) {
  .trust-center-v5 .trust-account-header,
  .trust-center-v5 .trust-control-strip,
  .trust-center-v5 .trust-center-grid {
    grid-template-columns: 1fr;
  }

  .trust-header-actions {
    justify-content: space-between;
  }

  .trust-snapshot-bar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .trust-snapshot-bar > div + div {
    border-left: 0;
  }

  .trust-snapshot-bar > div:nth-child(2n) {
    border-left: 1px solid var(--border-subtle);
  }

  .trust-snapshot-bar > div:nth-child(n + 3) {
    border-top: 1px solid var(--border-subtle);
  }
}

@media (max-width: 680px) {
  .trust-center-v5 .trust-account-header {
    padding: 14px;
  }

  .trust-header-actions,
  .trust-center-v5 .trust-quick-actions {
    align-items: stretch;
    flex-direction: column;
    width: 100%;
  }

  .trust-center-v5 .trust-quick-actions button,
  .trust-refresh-button {
    width: 100%;
  }

  .trust-snapshot-bar,
  .trust-center-v5 .fit-learning-card,
  .trust-center-v5 .fit-help-control,
  .trust-center-v5 .fit-journey-preview {
    grid-template-columns: 1fr;
  }

  .trust-snapshot-bar > div,
  .trust-snapshot-bar > div:nth-child(2n) {
    border-left: 0;
  }

  .trust-snapshot-bar > div + div {
    border-top: 1px solid var(--border-subtle);
  }

  .trust-center-v5 .fit-learning-card > .btn-primary {
    justify-self: stretch;
    width: 100%;
  }
}

/* Unboxed commerce shell: reduce borders, let spacing and type do the work */
.web-header.commerce-header {
  background: color-mix(in srgb, var(--bg-canvas) 92%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--border-subtle) 58%, transparent);
  box-shadow: none;
  padding: 14px var(--app-page-gutter) 10px;
}

.commerce-header-container {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin-inline: auto;
  max-width: min(var(--app-shell-max), 100%);
  min-height: 48px;
  padding: 0 !important;
}

.commerce-nav {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  gap: 18px;
  padding: 0 !important;
}

.commerce-nav button,
.commerce-role-lock {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  color: var(--text-secondary);
  min-height: 38px;
  padding: 6px 0 !important;
  position: relative;
}

.commerce-nav button::after {
  background: transparent;
  border-radius: 999px;
  bottom: 0;
  content: "";
  height: 3px;
  left: 0;
  position: absolute;
  right: 0;
}

.commerce-nav button.active {
  color: var(--text-primary) !important;
}

.commerce-nav button.active::after {
  background: var(--accent-primary);
}

.commerce-nav button:hover {
  color: var(--text-primary) !important;
}

.web-header-btn,
.web-header-select,
.commerce-account,
.commerce-mode-btn {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}

.web-header-btn,
.web-header-select {
  min-height: 36px;
  padding: 6px 4px !important;
}

.commerce-mode-btn {
  color: var(--success) !important;
}

.commerce-account {
  gap: 8px;
  padding: 0 !important;
}

.commerce-account-name small {
  color: var(--text-secondary);
}

.web-logout-btn {
  color: var(--accent-primary);
}

.web-brand-badge {
  border-radius: 10px;
}

/* Product detail: one clean product page, not stacked bordered boxes */
.product-detail-shell {
  gap: 18px;
}

.product-detail-header {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 0 auto;
  max-width: min(1320px, 100%);
  padding: 0 !important;
  width: 100%;
}

.product-detail-header button {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  height: auto;
  width: auto;
}

.product-detail-header button svg {
  color: var(--text-secondary);
}

.product-detail-header strong {
  color: var(--text-primary);
  font-size: 15px;
  font-weight: 700;
}

.web-detail-layout {
  align-items: start;
  gap: clamp(22px, 3.2vw, 42px);
  grid-template-columns: minmax(360px, 0.94fr) minmax(390px, 0.86fr);
  margin-inline: auto;
  max-width: min(1320px, 100%);
  width: 100%;
}

.detail-gallery-container,
.detail-info-container,
.detail-decision-container {
  gap: 18px;
}

.detail-decision-container {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  padding: 0 !important;
  position: sticky;
  top: 92px;
}

.detail-product-card {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  overflow: visible;
}

.detail-image-frame {
  background: var(--bg-surface-muted);
  border-radius: 16px;
  max-height: 480px;
  order: 2;
  overflow: hidden;
}

.detail-image-frame img {
  background: var(--bg-surface-muted);
}

.detail-image-frame span {
  background: rgba(20, 22, 28, 0.74);
  font-weight: 600;
}

.detail-product-summary {
  order: 1;
  padding: 0 0 14px !important;
}

.detail-product-summary > span {
  color: var(--text-secondary);
  font-weight: 600;
}

.detail-product-summary h1 {
