/* Knowledge graph interaction layer: click a node to isolate its proof path; ask a question to pulse the used facts. */
.kg-focus-strip {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  display: flex;
  gap: var(--space-2);
  min-height: 40px;
  padding: var(--space-2) var(--space-3);
}

.kg-focus-strip svg {
  color: var(--success);
  flex: 0 0 auto;
}

.kg-focus-strip span {
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.35;
}

.kg-focus-strip button {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 700;
  margin-left: auto;
  padding: 0;
}

.kg-focus-strip.pulse {
  animation: kg-focus-pulse 1.2s ease-in-out 2;
}

.kg-real-node,
.kg-real-edge,
.kg-real-edge-label {
  transition:
    opacity 180ms ease,
    filter 180ms ease,
    transform 180ms ease,
    box-shadow 180ms ease,
    stroke-width 180ms ease;
}

.kg-real-node.dimmed,
.kg-real-edge-label.dimmed {
  filter: grayscale(0.55);
  opacity: 0.28;
}

.kg-real-edge.dimmed {
  opacity: 0.12;
}

.kg-real-node.connected:not(.selected):not(.highlighted) {
  background: var(--bg-surface);
  border-color: color-mix(in srgb, var(--text-primary) 32%, var(--border-subtle));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--text-primary) 8%, transparent);
  opacity: 1;
}

.kg-real-edge.connected {
  opacity: 1;
  stroke: color-mix(in srgb, var(--text-primary) 74%, var(--success));
  stroke-width: 1.85;
}

.kg-real-edge-label.connected {
  background: var(--bg-surface);
  border-color: color-mix(in srgb, var(--text-primary) 24%, var(--border-subtle));
  color: var(--text-primary);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--text-primary) 8%, transparent);
  opacity: 1;
}

.kg-real-node.answer-pulse,
.kg-real-edge-label.answer-pulse {
  animation: kg-answer-node-pulse 1.15s ease-in-out 2;
}

.kg-real-edge.answer-pulse {
  animation: kg-answer-edge-pulse 1.15s ease-in-out 2;
  stroke-dasharray: 4 3;
}

@keyframes kg-focus-pulse {
  0%,
  100% {
    box-shadow: none;
  }
  50% {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent-primary) 14%, transparent);
  }
}

@keyframes kg-answer-node-pulse {
  0%,
  100% {
    transform: translate(-50%, -50%) scale(1);
  }
  50% {
    transform: translate(-50%, -50%) scale(1.015);
  }
}

@keyframes kg-answer-edge-pulse {
  0%,
  100% {
    stroke-width: 1.35;
  }
  50% {
    stroke-width: 2.2;
  }
}

@media (max-width: 560px) {
  .kg-focus-strip {
    align-items: flex-start;
  }

  .kg-focus-strip button {
    margin-left: 0;
  }
}

