  display: inline-flex;
  height: 38px;
  justify-content: center;
  width: 38px;
}

.proof-media-verdict {
  align-items: start;
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  display: grid;
  gap: 11px;
  grid-template-columns: 38px minmax(0, 1fr);
  padding: 13px;
}

.proof-media-verdict > span {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  display: inline-flex;
  height: 38px;
  justify-content: center;
  width: 38px;
}

.proof-media-verdict.approved {
  background: color-mix(in srgb, var(--success) 7%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 28%, var(--border-subtle));
}

.proof-media-verdict.approved > span {
  color: var(--success);
}

.proof-media-verdict.pending {
  background: color-mix(in srgb, var(--accent-primary) 6%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--accent-primary) 26%, var(--border-subtle));
}

.proof-media-verdict.pending > span {
  color: var(--accent-primary-hover);
}

.proof-media-verdict.rejected {
  background: color-mix(in srgb, var(--error) 6%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--error) 28%, var(--border-subtle));
}

.proof-media-verdict.rejected > span {
  color: var(--error);
}

.proof-media-verdict.waiting {
  background: color-mix(in srgb, var(--warning) 7%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--warning) 28%, var(--border-subtle));
}

.proof-media-verdict.waiting > span {
  color: var(--warning);
}

.proof-media-verdict strong {
  color: var(--text-primary);
  display: block;
  font-size: 16px;
  font-weight: 950;
  line-height: 1.25;
}

.proof-media-facts {
  display: grid;
  gap: 9px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.proof-media-facts div {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 11px;
}

.proof-media-facts span {
  color: var(--text-secondary);
  display: block;
  font-size: 10px;
  font-weight: 950;
  text-transform: uppercase;
}

.proof-media-facts strong {
  color: var(--text-primary);
  display: block;
  font-size: 14px;
  font-weight: 950;
  line-height: 1.2;
  margin-top: 3px;
}

.proof-media-review-note {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  color: var(--text-secondary);
  display: flex;
  font-size: 12px;
  font-weight: 750;
  gap: 8px;
  line-height: 1.4;
  padding: 10px 11px;
}

.proof-media-review-note svg {
  color: var(--success);
  flex: 0 0 auto;
}

.proof-media-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  justify-content: flex-end;
}

.proof-media-actions button {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  color: var(--text-primary);
  display: inline-flex;
  font-size: 13px;
  font-weight: 950;
  gap: 7px;
  min-height: 42px;
  padding: 9px 13px;
}

.proof-media-actions button.primary {
  background: var(--accent-primary);
  border-color: var(--accent-primary);
  color: var(--text-on-accent);
}

.sku-proof-dialog {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  box-shadow: 0 24px 70px color-mix(in srgb, var(--text-primary) 24%, transparent);
  max-width: 640px;
  padding: 16px;
  position: relative;
  width: min(640px, 100%);
}

.sku-proof-dialog-close {
  position: absolute;
  right: 14px;
  top: 14px;
  z-index: 1;
}

.sku-proof-dialog .sku-proof-spotlight {
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  color: var(--text-primary) !important;
  margin: 0 !important;
  padding: 0 !important;
}

.sku-proof-dialog .sku-proof-spotlight-head {
  border-bottom: 1px solid var(--border-subtle);
  padding: 4px 48px 14px 0;
}

.sku-proof-dialog .sku-proof-spotlight-head > span {
  background: color-mix(in srgb, var(--success) 10%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 28%, var(--border-subtle));
  color: var(--success);
}

.sku-proof-dialog .sku-proof-spotlight strong,
.sku-proof-dialog .sku-proof-spotlight b {
  color: var(--text-primary) !important;
}

.sku-proof-dialog .sku-proof-spotlight-head strong {
  font-size: 23px;
  letter-spacing: 0;
}

.sku-proof-dialog .sku-proof-spotlight-head p {
  color: var(--text-secondary) !important;
  font-size: 13px;
  line-height: 1.45;
  max-width: 520px;
}

.sku-proof-decision-row {
  display: grid;
  gap: 9px;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.sku-proof-decision-row div {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 11px;
  padding: 12px;
}

.sku-proof-decision-row span,
.sku-proof-decision-row small {
  color: var(--text-secondary);
  display: block;
  font-size: 10.5px;
  font-weight: 900;
}

.sku-proof-decision-row span {
  text-transform: uppercase;
}

.sku-proof-decision-row strong {
  color: var(--text-primary);
  display: block;
  font-size: 18px;
  font-weight: 950;
  line-height: 1;
  margin: 6px 0 4px;
}

.sku-proof-mini-flow {
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  display: grid;
  gap: 0;
  overflow: hidden;
}

.sku-proof-mini-flow span {
  align-items: center;
  color: var(--text-secondary);
  display: flex;
  font-size: 12px;
  font-weight: 800;
  gap: 9px;
  min-height: 42px;
  padding: 9px 11px;
}

.sku-proof-mini-flow span + span {
  border-top: 1px solid var(--border-subtle);
}

.sku-proof-mini-flow b {
  align-items: center;
  background: var(--text-primary);
  border-radius: 999px;
  color: var(--bg-surface) !important;
  display: inline-flex;
  flex: 0 0 auto;
  font-size: 11px;
  height: 22px;
  justify-content: center;
  width: 22px;
}

.sku-proof-dialog .sku-proof-actions {
  justify-content: flex-end;
}

.sku-proof-dialog .sku-proof-actions button {
  background: var(--bg-surface-muted) !important;
  border-color: var(--border-subtle) !important;
  color: var(--text-primary) !important;
}

.sku-proof-dialog .sku-proof-actions button:first-child {
  background: var(--accent-primary) !important;
  border-color: var(--accent-primary) !important;
  color: var(--text-on-accent) !important;
}

@media (max-width: 820px) {
  .proof-tracker-hero,
  .proof-safe-action {
    grid-template-columns: 1fr;
  }

  .proof-trust-score {
    border-left: 0;
    border-top: 1px solid var(--border-subtle);
    justify-items: start;
    padding-left: 0;
    padding-top: 10px;
    text-align: left;
  }
}

@media (max-width: 560px) {
  .buyer-workspace-header {
    display: grid !important;
    grid-template-columns: 1fr;
  }

  .proof-card-topline {
    grid-template-columns: 1fr;
  }

  .proof-decision-pill {
    justify-self: start;
  }

  .proof-tracker-card .proof-ledger-product {
    grid-template-columns: 58px minmax(0, 1fr) !important;
  }

  .proof-tracker-card .proof-ledger-product img {
    width: 58px;
  }

  .proof-ledger-actions {
    display: grid !important;
    grid-template-columns: 1fr 1fr;
  }

  .proof-ledger-actions button {
    width: 100%;
  }

  .proof-media-strip,
  .proof-media-dialog,
  .proof-media-facts,
  .sku-proof-decision-row {
    grid-template-columns: 1fr;
  }

  .proof-media-stage {
    min-height: 280px;
  }

  .proof-media-dialog-backdrop,
  .sku-proof-dialog-backdrop {
    align-items: stretch;
    padding: 10px;
  }

  .proof-media-dialog,
  .sku-proof-dialog {
    max-height: calc(100vh - 20px);
    overflow: auto;
  }

  .proof-media-actions,
  .sku-proof-dialog .sku-proof-actions {
    display: grid;
    grid-template-columns: 1fr;
  }
}

/* Dedicated checkout page: payment-first, no bottom-sheet clutter. */
.checkout-page-shell {
  display: grid;
  gap: 18px;
  margin: 0 auto;
  max-width: min(1240px, 100%);
  width: 100%;
}

.checkout-page-header {
  align-items: flex-start;
  display: grid;
  gap: 14px;
  grid-template-columns: auto minmax(0, 1fr);
}

.checkout-page-header button,
.checkout-page-secondary {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  color: var(--text-primary);
  cursor: pointer;
  display: inline-flex;
  font-size: 13px;
  font-weight: 900;
  gap: 7px;
  justify-content: center;
  min-height: 38px;
  padding: 8px 13px;
}

.checkout-page-header h1 {
  color: var(--text-primary);
  font-size: clamp(28px, 2.6vw, 40px);
  font-weight: 950;
  letter-spacing: 0;
  line-height: 1.05;
  margin: 2px 0 0;
}

.checkout-page-header p {
  color: var(--text-secondary);
  font-size: 15px;
  font-weight: 700;
  line-height: 1.4;
  margin: 6px 0 0;
  max-width: 720px;
}

.checkout-page-layout {
  align-items: start;
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 380px);
}

.checkout-page-main {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.checkout-page-item,
.checkout-payment-decision,
.checkout-wearer-page,
.checkout-page-details,
.checkout-summary-card,
.checkout-success-panel {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
}

.checkout-page-item {
  align-items: center;
  display: grid;
  gap: 14px;
  grid-template-columns: 88px minmax(0, 1fr);
  padding: 14px;
}

.checkout-page-item img {
  aspect-ratio: 4 / 5;
  background: var(--bg-surface-muted);
  border-radius: 10px;
  object-fit: cover;
  width: 88px;
}

.checkout-page-item span {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 850;
}

.checkout-page-item h2 {
  color: var(--text-primary);
  font-size: 20px;
  font-weight: 950;
  line-height: 1.18;
  margin: 3px 0 0;
}

.checkout-page-item p {
  color: var(--accent-primary-hover);
  font-size: 13px;
  font-weight: 900;
  margin: 6px 0 0;
}

.checkout-payment-decision {
  align-items: center;
  display: grid;
  gap: 18px;
  grid-template-columns: minmax(0, 1fr) 180px;
  padding: 18px;
}

.checkout-payment-decision.prepaid {
  background: color-mix(in srgb, var(--success) 9%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 34%, var(--border-subtle));
}

.checkout-payment-decision.cod {
  background: color-mix(in srgb, var(--warning) 10%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--warning) 34%, var(--border-subtle));
}

.checkout-payment-decision h2 {
  color: var(--text-primary);
  font-size: clamp(24px, 2vw, 32px);
  font-weight: 950;
  line-height: 1.08;
  margin: 4px 0 0;
}

.checkout-payment-decision p {
  color: var(--text-secondary);
  font-size: 14px;
  font-weight: 750;
  line-height: 1.42;
  margin: 8px 0 0;
  max-width: 620px;
}

.checkout-benefit-chip {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  display: grid;
  gap: 4px;
  padding: 13px;
}

.checkout-benefit-chip span,
.checkout-benefit-chip small,
.checkout-summary-row span,
.checkout-summary-price span {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 850;
}

.checkout-benefit-chip strong {
  color: var(--success);
  font-size: 26px;
  font-weight: 950;
  line-height: 1;
}

.checkout-payment-options-page {
  display: grid;
  gap: 12px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.checkout-pay-card {
  align-items: start;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  color: var(--text-primary);
  cursor: pointer;
  display: grid;
  gap: 12px;
  grid-template-columns: 42px minmax(0, 1fr) 20px;
  min-height: 146px;
  padding: 15px;
  text-align: left;
}

.checkout-pay-card.recommended {
  border-color: color-mix(in srgb, var(--success) 34%, var(--border-subtle));
}

.checkout-pay-card.selected {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--accent-primary) 42%, transparent);
}

.checkout-pay-card:disabled {
  cursor: not-allowed;
  opacity: 0.65;
}

.checkout-pay-icon {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 999px;
  color: var(--text-primary);
  display: inline-flex;
  height: 42px;
  justify-content: center;
  width: 42px;
}

.checkout-pay-card.prepaid.recommended .checkout-pay-icon,
.checkout-pay-card.selected .checkout-pay-icon {
  background: color-mix(in srgb, var(--success) 12%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 32%, var(--border-subtle));
  color: var(--success);
}

.checkout-pay-card em,
.checkout-offer-strip > span {
  color: var(--accent-primary-hover);
  display: block;
  font-size: 11px;
  font-style: normal;
  font-weight: 950;
  text-transform: uppercase;
}

.checkout-pay-card strong {
  color: var(--text-primary);
  display: block;
  font-size: 20px;
  font-weight: 950;
  line-height: 1.1;
  margin-top: 6px;
}

.checkout-pay-card small {
  color: var(--text-secondary);
  display: block;
  font-size: 13px;
  font-weight: 750;
  line-height: 1.35;
  margin-top: 7px;
}

.checkout-pay-card > svg {
  color: var(--success);
  margin-top: 3px;
}

.checkout-offer-strip {
  align-items: center;
  background: var(--bg-surface);
  border: 1px dashed color-mix(in srgb, var(--success) 34%, var(--border-subtle));
  border-radius: 12px;
  display: grid;
  gap: 10px;
  grid-template-columns: auto minmax(0, 1fr);
  padding: 12px 14px;
}

.checkout-offer-strip div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.checkout-offer-strip b {
  background: var(--bg-surface-muted);
  border-radius: 999px;
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 850;
  padding: 6px 9px;
}

.checkout-offer-strip b.eligible {
  background: color-mix(in srgb, var(--success) 11%, var(--bg-surface));
  color: var(--success);
}

.checkout-wearer-page {
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(0, 1fr) auto;
  padding: 15px;
}

.checkout-wearer-page h3 {
  color: var(--text-primary);
  font-size: 18px;
  font-weight: 950;
  margin: 3px 0 0;
}

.checkout-wearer-page p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.4;
  margin: 5px 0 0;
}

.checkout-wearer-toggle-page {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  display: inline-flex;
  gap: 4px;
  padding: 4px;
}

.checkout-wearer-toggle-page button {
  background: transparent;
  border: 0;
  border-radius: 9px;
  color: var(--text-secondary);
  cursor: pointer;
  font-size: 13px;
  font-weight: 900;
  min-height: 34px;
  padding: 7px 10px;
}

.checkout-wearer-toggle-page button.active {
  background: var(--text-primary);
  color: var(--bg-surface);
}

.checkout-page-details {
  overflow: hidden;
}

.checkout-page-details summary {
  color: var(--text-primary);
  cursor: pointer;
  font-size: 14px;
  font-weight: 950;
  list-style: none;
  min-height: 48px;
  padding: 15px;
}

.checkout-page-details summary::-webkit-details-marker {
  display: none;
}

.checkout-page-detail-grid {
  border-top: 1px solid var(--border-subtle);
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.checkout-page-detail-grid div {
  display: grid;
  gap: 4px;
  padding: 13px 15px;
}

.checkout-page-detail-grid div + div {
  border-left: 1px solid var(--border-subtle);
}

.checkout-page-detail-grid span,
.checkout-page-detail-grid small {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 800;
  line-height: 1.3;
}

.checkout-page-detail-grid strong {
  color: var(--text-primary);
  font-size: 20px;
  font-weight: 950;
  line-height: 1;
}

.checkout-contract-mini {
  border-top: 1px solid var(--border-subtle);
  padding: 13px 15px;
}

.checkout-contract-mini strong {
  color: var(--text-primary);
  display: block;
  font-size: 14px;
  font-weight: 950;
}

.checkout-contract-mini p {
  color: var(--text-secondary);
  font-size: 13px;
  line-height: 1.4;
  margin: 5px 0 0;
}

.checkout-page-summary {
  position: sticky;
  top: 92px;
}

.checkout-summary-card {
  display: grid;
  gap: 13px;
  padding: 16px;
}

.checkout-summary-price {
  align-items: baseline;
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  justify-content: space-between;
  padding-bottom: 12px;
}

.checkout-summary-price strong {
  color: var(--text-primary);
  font-size: 30px;
  font-weight: 950;
  line-height: 1;
}

.checkout-summary-row {
  align-items: center;
  display: flex;
  justify-content: space-between;
}

.checkout-summary-row b {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 950;
}

.checkout-summary-row.benefit b {
  color: var(--success);
}

.checkout-summary-safety {
  background: var(--bg-surface-muted);
  border-radius: 12px;
  display: grid;
  gap: 7px;
  padding: 11px;
}

.checkout-summary-safety span {
  align-items: center;
  color: var(--text-primary);
  display: inline-flex;
  font-size: 12px;
  font-weight: 900;
  gap: 7px;
}

.checkout-summary-safety svg {
  color: var(--success);
}

.checkout-page-primary {
  align-items: center;
  background: var(--accent-primary);
  border: 1px solid var(--accent-primary);
  border-radius: 11px;
  color: var(--text-on-accent);
  cursor: pointer;
  display: inline-flex;
  font-size: 14px;
  font-weight: 950;
  justify-content: center;
  min-height: 46px;
  padding: 10px 14px;
  width: 100%;
}

.checkout-page-primary:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.checkout-summary-note {
  color: var(--text-secondary);
  font-size: 12px;
  font-weight: 750;
  line-height: 1.35;
  text-align: center;
}

.checkout-success-panel {
  align-items: center;
  display: grid;
  gap: 16px;
  justify-items: center;
  margin: 40px auto 0;
  max-width: 560px;
  min-height: 360px;
  padding: 32px;
  text-align: center;
}

.checkout-success-icon {
  align-items: center;
  background: color-mix(in srgb, var(--success) 12%, var(--bg-surface));
  border-radius: 999px;
  color: var(--success);
  display: inline-flex;
  height: 64px;
  justify-content: center;
  width: 64px;
}

.checkout-success-panel h1 {
  color: var(--text-primary);
  font-size: 30px;
  font-weight: 950;
  line-height: 1.1;
  margin: 4px 0 0;
}

.checkout-success-panel p {
  color: var(--text-secondary);
  font-size: 14px;
  line-height: 1.45;
  margin: 8px 0 0;
}

.checkout-success-actions {
  display: grid;
  gap: 10px;
  max-width: 320px;
  width: 100%;
}

@media (max-width: 980px) {
  .checkout-page-layout,
  .checkout-payment-decision,
  .checkout-wearer-page {
    grid-template-columns: 1fr;
  }

  .checkout-page-summary {
    position: static;
  }
}

@media (max-width: 680px) {
  .checkout-page-header,
  .checkout-page-item,
  .checkout-payment-options-page,
  .checkout-offer-strip,
  .checkout-page-detail-grid {
    grid-template-columns: 1fr;
  }

  .checkout-page-item img {
    width: min(120px, 42vw);
  }

  .checkout-page-detail-grid div + div {
    border-left: 0;
    border-top: 1px solid var(--border-subtle);
  }

