  gap: 16px;
  min-width: 0;
}

.admin-impact-band,
.admin-policy-strip {
  display: grid;
  gap: 10px;
}

.admin-impact-band {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.admin-policy-strip {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.admin-upload-ledger,
.admin-priority-table,
.admin-dossier-list,
.admin-check-list,
.admin-source-list,
.admin-impact-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.admin-review-section,
.admin-policy-card,
.admin-command-panel,
.admin-ai-health-card {
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 10px !important;
  box-shadow: none !important;
}

.admin-section-heading {
  border-bottom: 1px solid var(--border-subtle);
  margin-bottom: 12px !important;
  padding-bottom: 12px;
}

.admin-section-heading h3,
.admin-policy-card h3,
.admin-command-panel h3 {
  color: var(--text-primary);
  font-size: 17px !important;
  line-height: 1.2;
}

.admin-section-heading p,
.admin-policy-card p,
.admin-command-panel p {
  color: var(--text-secondary);
  font-size: 12.5px !important;
  line-height: 1.45;
}

.admin-review-card,
.admin-upload-row,
.admin-priority-row,
.admin-dossier-card,
.admin-check-row,
.admin-source-row,
.admin-impact-item,
.admin-doc-row {
  background: var(--bg-surface-muted) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 8px !important;
  box-shadow: none !important;
}

.admin-upload-row {
  display: grid;
  gap: 10px;
  grid-template-columns: minmax(180px, 1fr) auto;
  padding: 12px;
}

.admin-upload-main h4,
.admin-priority-copy h4,
.admin-impact-item h4,
.admin-dossier-card h4 {
  color: var(--text-primary) !important;
  font-size: 15px !important;
  line-height: 1.25;
}

.admin-upload-main p,
.admin-priority-copy p,
.admin-impact-item p,
.admin-dossier-card p {
  color: var(--text-secondary);
  font-size: 12.5px;
  line-height: 1.45;
}

.admin-upload-facts {
  display: grid;
  gap: 8px;
  grid-column: 1 / -1;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.admin-upload-row .admin-prescreen,
.admin-upload-row .admin-evidence-preview,
.admin-upload-row textarea,
.admin-upload-row .admin-action-row {
  grid-column: 1 / -1;
}

.admin-evidence-preview {
  align-items: center;
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  display: grid;
  gap: 10px;
  grid-template-columns: 74px minmax(0, 1fr);
  padding: 8px;
}

.admin-preview-thumb {
  align-items: center;
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 7px;
  color: var(--text-secondary);
  display: grid;
  height: 58px;
  justify-items: center;
  overflow: hidden;
  padding: 6px;
}

.admin-preview-thumb img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.admin-preview-thumb span {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 900;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-evidence-preview strong {
  color: var(--text-primary);
  display: block;
  font-size: 12.5px;
  line-height: 1.25;
}

.admin-evidence-preview span,
.admin-evidence-preview em {
  color: var(--text-secondary);
  display: flex;
  gap: 5px;
  align-items: center;
  font-size: 11px;
  font-style: normal;
  line-height: 1.35;
  margin-top: 3px;
  overflow-wrap: anywhere;
}

.admin-evidence-preview em {
  color: var(--warning);
}

.admin-prescreen {
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  display: grid;
  gap: 6px;
  margin: 10px 0;
  padding: 10px;
}

.admin-prescreen.compact {
  margin: 0;
}

.admin-prescreen-line {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.admin-prescreen-line span {
  color: var(--text-primary);
  font-size: 12px;
  font-weight: 900;
  text-transform: capitalize;
}

.admin-prescreen-line small,
.admin-prescreen p {
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 1.4;
}

.admin-status-badge,
.admin-risk-badge {
  border-radius: 6px !important;
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 4px 8px !important;
  text-transform: capitalize !important;
}

.admin-risk-badge {
  border: 1px solid var(--border-subtle);
  color: var(--text-primary);
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.admin-status-badge.good,
.admin-risk-badge.good {
  background: color-mix(in srgb, var(--success) 12%, var(--bg-surface)) !important;
  border-color: color-mix(in srgb, var(--success) 35%, var(--border-subtle)) !important;
  color: var(--success) !important;
}

.admin-status-badge.attention,
.admin-risk-badge.attention {
  background: color-mix(in srgb, var(--warning) 14%, var(--bg-surface)) !important;
  border-color: color-mix(in srgb, var(--warning) 40%, var(--border-subtle)) !important;
  color: var(--warning) !important;
}

.admin-status-badge.bad,
.admin-risk-badge.bad {
  background: color-mix(in srgb, var(--error) 13%, var(--bg-surface)) !important;
  border-color: color-mix(in srgb, var(--error) 40%, var(--border-subtle)) !important;
  color: var(--error) !important;
}

.admin-status-badge.neutral,
.admin-risk-badge.neutral {
  background: var(--bg-surface) !important;
  border-color: var(--border-subtle) !important;
  color: var(--text-secondary) !important;
}

.admin-detail-grid.compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.admin-detail {
  background: var(--bg-surface) !important;
  border-color: var(--border-subtle) !important;
  border-radius: 7px !important;
}

.admin-detail strong {
  color: var(--text-primary) !important;
}

.admin-review-card textarea,
.admin-upload-row textarea {
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 8px !important;
  color: var(--text-primary);
  min-height: 58px !important;
}

.admin-command-panel {
  background: var(--text-primary) !important;
  color: var(--bg-canvas);
  display: grid;
  gap: 14px;
  grid-template-columns: minmax(0, 1fr) auto;
}

.admin-command-panel .eyebrow,
.admin-command-panel h3,
.admin-command-panel p {
  color: var(--bg-canvas) !important;
}

.admin-agent-provider {
  align-items: center;
  background: color-mix(in srgb, var(--bg-canvas) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--bg-canvas) 24%, transparent);
  border-radius: 8px;
  display: inline-flex;
  gap: 8px;
  height: fit-content;
  padding: 8px 10px;
}

.admin-agent-provider span {
  color: var(--bg-canvas);
  font-size: 12px;
  font-weight: 900;
  text-transform: capitalize;
}

.admin-command-steps {
  display: grid;
  gap: 8px;
  grid-column: 1 / -1;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.admin-command-step {
  background: color-mix(in srgb, var(--bg-canvas) 9%, transparent);
  border: 1px solid color-mix(in srgb, var(--bg-canvas) 18%, transparent);
  border-radius: 8px;
  display: grid;
  gap: 6px;
  padding: 10px;
}

.admin-command-step strong {
  color: var(--success);
}

.admin-command-step span,
.admin-agent-caution {
  color: color-mix(in srgb, var(--bg-canvas) 78%, transparent);
  font-size: 12px;
  line-height: 1.4;
}

.admin-agent-caution {
  align-items: center;
  border-top: 1px solid color-mix(in srgb, var(--bg-canvas) 18%, transparent);
  display: flex;
  gap: 8px;
  grid-column: 1 / -1;
  padding-top: 10px;
}

.admin-ai-health-card {
  display: grid;
  gap: 12px;
  padding: 16px !important;
}

.admin-ai-health-status,
.admin-ai-test-result {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  display: grid;
  gap: 6px;
  padding: 10px;
}

.admin-ai-health-status strong,
.admin-ai-test-result strong {
  color: var(--text-primary);
  font-size: 13px;
  overflow-wrap: anywhere;
}

.admin-ai-health-status span,
.admin-ai-test-result span {
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.4;
}

.admin-priority-row {
  align-items: start;
  display: grid;
  gap: 12px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 12px;
}

.admin-priority-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 8px;
}

.admin-priority-meta span {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 11px;
  font-weight: 800;
  padding: 5px 7px;
}

.admin-priority-status {
  align-items: flex-end;
  display: flex;
  flex-direction: column;
  gap: 6px;
  white-space: nowrap;
}

.admin-priority-status small {
  color: var(--text-muted);
  font-size: 11px;
}

.admin-dossier-card {
  display: grid;
  gap: 10px;
  padding: 12px;
}

.admin-dossier-score {
  align-items: center;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  display: grid;
  gap: 8px;
  grid-template-columns: auto auto minmax(0, 1fr);
  padding: 9px;
}

.admin-dossier-score strong {
  color: var(--text-primary);
  font-size: 20px;
  line-height: 1;
}

.admin-dossier-score span {
  color: var(--text-secondary);
  font-size: 11px;
}

.admin-check-row,
.admin-source-row,
.admin-impact-item {
  align-items: center;
  display: grid;
  gap: 12px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  padding: 12px;
}

.admin-check-row strong,
.admin-source-row strong {
  color: var(--text-primary);
  display: block;
  font-size: 13px;
}

.admin-check-row span,
.admin-check-row small,
.admin-source-row span {
  color: var(--text-secondary);
  font-size: 11.5px;
  line-height: 1.35;
}

.admin-source-overall {
  background: var(--text-primary);
  border-radius: 8px;
  color: var(--bg-canvas);
  display: grid;
  gap: 4px;
  padding: 12px;
}

.admin-source-overall strong {
  color: var(--bg-canvas);
  font-size: 16px;
  text-transform: capitalize;
}

.admin-source-overall span {
  color: color-mix(in srgb, var(--bg-canvas) 72%, transparent);
  font-size: 12px;
}

.admin-human-loop-card .policy-list span {
  background: var(--bg-surface-muted) !important;
  border-color: var(--border-subtle) !important;
  border-radius: 7px !important;
}

.admin-impact-item {
  grid-template-columns: minmax(0, 1fr) auto;
}

.admin-impact-score {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  display: grid;
  min-width: 96px;
  padding: 9px;
  text-align: right;
}

.admin-impact-score strong {
  color: var(--success);
  font-size: 20px;
  line-height: 1;
}

.admin-impact-score span {
  color: var(--text-secondary);
  font-size: 10.5px;
}

@media (max-width: 1100px) {
  .admin-agent-layout,
  .admin-policy-layout,
  .admin-impact-grid {
    grid-template-columns: 1fr;
  }

  .admin-impact-band,
  .admin-stats-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .admin-review-shell .admin-hero {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .admin-review-shell .admin-hero h2 {
    font-size: 28px !important;
  }

  .admin-impact-band,
  .admin-policy-strip,
  .admin-command-steps,
  .admin-detail-grid,
  .admin-detail-grid.compact,
  .admin-upload-facts {
    grid-template-columns: 1fr;
  }

  .admin-upload-row,
  .admin-priority-row,
  .admin-check-row,
  .admin-source-row,
  .admin-impact-item {
    grid-template-columns: 1fr;
  }

  .admin-priority-status {
    align-items: flex-start;
  }
}

/* Buyer trust center: simple size memory timeline for non-technical buyers. */
.trust-center-v5 .proof-checklist-card {
