  font-size: 11px;
  color: var(--text-muted);
}

.truth-card-reason-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  padding: 16px;
}

.truth-score-reason, .truth-risk-stack {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.truth-score-reason span,
.truth-risk-stack span {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

.truth-score-reason strong,
.truth-risk-stack strong {
  font-size: 14px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.35;
}

.truth-score-reason p,
.truth-risk-stack p {
  font-size: 12.5px;
  color: var(--text-secondary);
  line-height: 1.45;
  margin: 0;
}

.truth-score-reason div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 4px;
}

.truth-score-reason small {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: color-mix(in srgb, var(--success) 6%, var(--bg-surface-muted));
  color: var(--success);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 11px;
  font-weight: 750;
}

.truth-score-reason small.watch {
  background: color-mix(in srgb, var(--warning) 6%, var(--bg-surface-muted));
  color: var(--warning);
}

.truth-risk-stack > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.truth-risk-stack > div.watch strong {
  color: var(--warning);
}

.truth-card-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  border-top: 1px solid var(--border-subtle);
  padding-top: 14px;
  margin-top: 6px;
}

.truth-card-footer > span {
  font-size: 12px;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.truth-card-footer div {
  display: flex;
  gap: 8px;
}

.truth-card-footer button {
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 8px !important;
  color: var(--text-primary) !important;
  font-size: 12px !important;
  font-weight: 800 !important;
  padding: 6px 12px !important;
  cursor: pointer !important;
  min-height: 32px !important;
  transition: var(--transition) !important;
}

.truth-card-footer button:hover {
  background: var(--bg-surface-muted) !important;
  border-color: var(--text-muted) !important;
}

.truth-proof-loop-notice {
  display: flex;
  align-items: center;
  gap: 6px;
  background: color-mix(in srgb, var(--accent-primary) 6%, var(--bg-surface));
  border: 1px solid color-mix(in srgb, var(--accent-primary) 15%, var(--border-subtle));
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 12.5px;
  color: var(--accent-primary);
}

/* -------------------------------------------------------------
   SCORE REASON SUMMARY Polish
------------------------------------------------------------- */
.score-reason-summary {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 20px !important;
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 16px;
}

.score-reason-summary > div:first-child {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.score-reason-summary strong {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
  margin-top: 4px;
}

.score-reason-summary small {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.45;
  margin-top: 2px;
}

.score-reason-columns {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  border-top: 1px solid var(--border-subtle);
  padding-top: 16px;
}

.score-reason-columns > div {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.score-reason-columns span {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text-muted);
  letter-spacing: 0.5px;
  margin-bottom: 2px;
}

.score-reason-columns b {
  font-size: 12.5px;
  font-weight: 750;
  color: var(--text-primary);
  display: inline-flex;
  align-items: start;
  gap: 6px;
  line-height: 1.35;
}

.score-reason-columns b svg {
  margin-top: 2px;
  flex-shrink: 0;
}

.score-reason-columns > div:first-of-type b svg {
  color: var(--success);
}

.score-reason-columns > div:last-of-type b svg {
  color: var(--warning);
}

/* -------------------------------------------------------------
   REVIEW CREDIBILITY STRIP Polish
------------------------------------------------------------- */
.review-credibility-strip {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 16px;
  padding: 20px !important;
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-bottom: 16px;
}

.review-credibility-head {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: 16px;
}

.review-credibility-head > div {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.review-credibility-head strong {
  font-size: 18px;
  font-weight: 800;
  color: var(--text-primary);
  margin-top: 4px;
}

.review-credibility-head small {
  font-size: 13px;
  color: var(--text-secondary);
  line-height: 1.45;
  margin-top: 2px;
}

.review-spike-pill {
  align-items: center;
  background: color-mix(in srgb, var(--success) 8%, var(--bg-surface));
  border: 1px solid color-mix(in srgb, var(--success) 24%, var(--border-subtle));
  border-radius: 999px;
  color: var(--success);
  display: inline-flex;
  font-size: 11.5px;
  font-weight: 800;
  gap: 5px;
  min-height: 30px;
  padding: 6px 9px;
  white-space: nowrap;
}

.review-spike-pill.watch {
  background: color-mix(in srgb, var(--warning) 9%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--warning) 24%, var(--border-subtle));
  color: var(--warning);
}

.review-credibility-metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
  padding: 14px 0;
}

.review-credibility-metrics span {
  font-size: 11px;
  color: var(--text-muted);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
}

.review-credibility-metrics b {
  font-size: 24px;
  font-weight: 900;
  color: var(--text-primary);
  line-height: 1;
}

.review-check-grid {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.review-check-grid article {
  align-items: flex-start;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  display: grid;
  gap: 8px;
  grid-template-columns: 16px minmax(0, 1fr);
  padding: 10px;
}

.review-check-grid article.good svg {
  color: var(--success);
}

.review-check-grid article.watch svg {
  color: var(--warning);
}

.review-check-grid span,
.review-downweight-list span {
  color: var(--text-muted);
  display: block;
  font-size: 11px;
  font-weight: 750;
}

.review-check-grid strong,
.review-downweight-list strong {
  color: var(--text-primary);
  display: block;
  font-size: 13px;
  line-height: 1.25;
}

.review-downweight-details {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  padding: 0;
}

.review-downweight-details summary {
  color: var(--text-primary);
  cursor: pointer;
  font-size: 13px;
  font-weight: 800;
  list-style: none;
  padding: 12px;
}

.review-downweight-details summary::-webkit-details-marker {
  display: none;
}

.review-downweight-list {
  border-top: 1px solid var(--border-subtle);
  display: grid;
  gap: 10px;
  padding: 12px;
}

.review-downweight-list article {
  display: grid;
  gap: 8px;
}

.review-downweight-list article + article {
  border-top: 1px solid color-mix(in srgb, var(--border-subtle) 70%, transparent);
  padding-top: 10px;
}

.review-downweight-list p,
.review-trust-answer {
  color: var(--text-secondary);
  font-size: 12.5px;
  line-height: 1.45;
  margin: 4px 0 0;
}

.review-warning-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.review-warning-tags span {
  align-items: center;
  background: color-mix(in srgb, var(--warning) 8%, var(--bg-surface-muted));
  border-radius: 999px;
  color: var(--warning);
  display: inline-flex;
  gap: 4px;
  min-height: 26px;
  padding: 5px 8px;
}

.review-warning-tags span.good {
  background: color-mix(in srgb, var(--success) 8%, var(--bg-surface-muted));
  color: var(--success);
}

.review-warning-tags span.high {
  background: color-mix(in srgb, var(--error) 7%, var(--bg-surface-muted));
  color: var(--error);
}

.review-trust-answer {
  align-items: flex-start;
  background: color-mix(in srgb, var(--accent-primary) 5%, var(--bg-surface));
  border: 1px solid color-mix(in srgb, var(--accent-primary) 15%, var(--border-subtle));
  border-radius: 12px;
  display: grid;
  gap: 7px;
  grid-template-columns: 15px minmax(0, 1fr);
  padding: 10px 12px;
}

.review-trust-answer svg {
  color: var(--accent-primary);
  margin-top: 2px;
}

.review-credibility-flags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.review-credibility-flags span {
  background: color-mix(in srgb, var(--border-subtle) 40%, var(--bg-surface));
  border: 1px solid var(--border-subtle);
  border-radius: 6px;
  padding: 4px 8px;
  font-size: 11px;
  font-weight: 750;
  color: var(--text-secondary);
}

.response-actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
}

.response-actions button {
  background: var(--bg-surface) !important;
  border: 1px solid var(--border-subtle) !important;
  border-radius: 8px !important;
  color: var(--text-primary) !important;
  font-size: 12px !important;
  font-weight: 800 !important;
  padding: 6px 12px !important;
  cursor: pointer !important;
  min-height: 32px !important;
  transition: var(--transition) !important;
}

.response-actions button:hover {
  background: var(--bg-surface-muted) !important;
}

.response-actions button.btn-action-primary {
  background: var(--accent-primary) !important;
  border-color: var(--accent-primary) !important;
  color: var(--text-on-accent) !important;
}

.response-actions button.btn-action-primary:hover {
  opacity: 0.9 !important;
}

/* -------------------------------------------------------------
   RESPONSIVENESS FOR THE Polish
------------------------------------------------------------- */
@media (max-width: 680px) {
  .score-reason-columns,
  .review-credibility-metrics,
  .review-check-grid {
    grid-template-columns: 1fr;
  }
}


/* -------------------------------------------------------------
   MOBILE PRODUCT CARD PREMIUM POLISH
------------------------------------------------------------- */
@media (max-width: 768px) {
