    width: 100% !important;
    min-height: 36px !important;
    padding: 8px 12px !important;
    border-radius: 8px !important;
    background: var(--text-primary) !important;
    color: var(--bg-surface) !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 6px !important;
    border: none !important;
    margin: 0 !important;
    box-shadow: var(--shadow-sm) !important;
    transition: background 150ms ease !important;
  }

  .buyer-product-actions.compact button.primary:hover {
    background: color-mix(in srgb, var(--text-primary) 85%, transparent) !important;
  }

  .buyer-product-actions.compact button.primary span {
    font-size: 12.5px !important;
    font-weight: 800 !important;
  }

  /* Make the title text, kicker, and price row clean and modern */
  .buyer-card-kicker {
    display: flex !important;
    justify-content: space-between !important;
    align-items: center !important;
    font-size: 11px !important;
    color: var(--text-secondary) !important;
    margin-bottom: 2px !important;
  }

  .buyer-product-title {
    font-size: 13px !important;
    font-weight: 700 !important;
    color: var(--text-primary) !important;
    text-align: left !important;
    line-height: 1.35 !important;
    margin: 0 !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    min-height: 36px !important;
  }

  .product-price-row {
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    margin-top: 2px !important;
  }

  .product-price-row strong {
    font-size: 15px !important;
    font-weight: 900 !important;
    color: var(--text-primary) !important;
  }

  .product-price-row span {
    font-size: 9.5px !important;
    font-weight: 800 !important;
    padding: 2px 6px !important;
    border-radius: 4px !important;
    background: color-mix(in srgb, var(--accent-primary) 7%, var(--bg-surface-muted)) !important;
    border: 1px solid color-mix(in srgb, var(--accent-primary) 15%, var(--border-subtle)) !important;
    color: var(--accent-primary) !important;
  }

  /* Make details rows look premium */
  .buyer-delivery-row,
  .product-trust-phrase {
    display: flex !important;
    align-items: center !important;
