/* -------------------------------------------------------------
   SARTHI TRUST RUN SUMMARY DASHBOARD Polish (Anti-Run-Together & Unspaced text)
------------------------------------------------------------- */
.trust-run-card {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  padding: 16px !important;
  margin: 16px 0 !important;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.trust-run-card-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 12px;
}

.trust-run-card-header h4 {
  font-size: 15px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 4px 0 0;
  line-height: 1.35;
}

.trust-run-score {
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 6px 12px;
  font-size: 16px;
  font-weight: 900;
  color: var(--text-primary);
  white-space: nowrap;
  box-shadow: var(--shadow-sm);
}

.trust-run-score.strong {
  color: var(--success);
  border-color: color-mix(in srgb, var(--success) 24%, var(--border-subtle));
}

.trust-run-score.watch {
  color: var(--warning);
  border-color: color-mix(in srgb, var(--warning) 24%, var(--border-subtle));
}

.trust-run-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px; /* Adds explicit horizontal and vertical gap between spans */
  border-bottom: 1px solid var(--border-subtle);
  padding-bottom: 12px;
  margin-bottom: 4px;
}

.trust-run-meta span {
  font-size: 11px;
  font-weight: 750;
  text-transform: uppercase;
  color: var(--text-secondary);
  background: color-mix(in srgb, var(--border-subtle) 25%, var(--bg-surface));
  padding: 4px 8px;
  border-radius: 6px;
  border: 1px solid var(--border-subtle);
  display: inline-flex;
  align-items: center;
}

.trust-run-timeline {
  list-style: none !important; /* Removes default ordered list browser numbering prefix 1. 2. 3. */
  padding: 0 !important;
  margin: 0 !important;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.trust-run-step {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: start;
  background: var(--bg-surface);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 10px 12px;
  list-style-type: none !important; /* Extra safety for browser numbering */
}

.trust-run-step-mark {
  background: var(--bg-surface-muted);
  border: 1px solid var(--border-subtle);
  color: var(--text-secondary);
  width: 24px;
  height: 24px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 900;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.trust-run-step.done .trust-run-step-mark {
  background: color-mix(in srgb, var(--success) 8%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--success) 30%, var(--border-subtle));
  color: var(--success);
}

.trust-run-step.watch .trust-run-step-mark {
  background: color-mix(in srgb, var(--warning) 8%, var(--bg-surface));
  border-color: color-mix(in srgb, var(--warning) 30%, var(--border-subtle));
  color: var(--warning);
}

.trust-run-step div {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.trust-run-step strong {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.3;
}

.trust-run-step small {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
}

.trust-run-step b {
  font-size: 13.5px;
  font-weight: 800;
  color: var(--text-primary);
  white-space: nowrap;
  margin-top: 2px;
  align-self: flex-start;
}

/* Make similar sellers cards in comparison sheet interactive and hoverable */
.compare-similar-card {
  cursor: pointer !important;
  transition: transform 150ms ease, border-color 150ms ease, box-shadow 150ms ease !important;
}

.compare-similar-card:hover {
  border-color: color-mix(in srgb, var(--accent-primary) 35%, var(--border-subtle)) !important;
  box-shadow: var(--shadow-sm) !important;
  transform: translateY(-1px) !important;
}


